import { Token } from '@cetus/types'
import { AllTokensTable } from '@cetus/utils'
import { fixCoinType } from '@cetusprotocol/common-sdk'
import { useDeepCompareEffect } from 'ahooks'
import { useState } from 'react'
import { useGetTokens } from './useGetTokens'

type TokenInfoType<T> = T extends string ? Token | undefined : T extends string[] ? Map<string, Token> | undefined : undefined

export function useGetToken<T extends string | string[] | undefined>(coinType?: T) {
  const { getToken, getTokenList } = useGetTokens()
  const [tokenInfo, setTokenInfo] = useState<TokenInfoType<T>>()
  useDeepCompareEffect(() => {
    if (coinType) {
      fetchTokenInfo(coinType).then(tokenInfo => {
        setTokenInfo(tokenInfo)
      })
    }
  }, [coinType])

  const fetchTokenInfo = async <K extends string | string[]>(coinType: K): Promise<TokenInfoType<K>> => {
    try {
      if (Array.isArray(coinType)) {
        const tokenMap = await getTokenListInfo(coinType)
        return tokenMap as TokenInfoType<K>
      } else {
        const token = await getTokenInfo(coinType)
        if (token) {
          return token as TokenInfoType<K>
        }
      }
    } catch (error) {
      console.log('🚀 ~ file: useToken.ts:32 ~ fetchTokenInfo ~ error:', error)
    }

    return undefined as TokenInfoType<K>
  }

  const getTokenInfo = async (coinType?: string) => {
    try {
      if (coinType) {
        const token = await AllTokensTable.getItem<Token>(fixCoinType(coinType, false))
        if (token) {
          return token
        } else {
          await getToken(coinType)
          return AllTokensTable.getItem<Token>(fixCoinType(coinType, false))
        }
      }
      return undefined
    } catch (error) {
      console.log('🚀 ~ getTokenInfo ~ 51:', error)
      return undefined
    }
  }

  const getTokenListInfo = async (coinTypes?: string[]) => {
    try {
      if (coinTypes && coinTypes.length > 0) {
        const tokenMap = new Map<string, Token>()
        const unStoredTypes: string[] = []
        for (const coinType of coinTypes) {
          const token = await AllTokensTable.getItem<Token>(fixCoinType(coinType, false))
          if (token) {
            tokenMap.set(coinType, token)
          } else {
            unStoredTypes.push(coinType)
          }
        }
        if (unStoredTypes.length > 0) {
          await getTokenList(unStoredTypes)
        }
        for (const coinType of unStoredTypes) {
          const _token = await AllTokensTable.getItem<Token>(fixCoinType(coinType, false))
          if (_token) {
            tokenMap.set(coinType, _token)
          }
        }
        // console.log('getTokenListInfo tokenMap', tokenMap)
        return tokenMap
      }
      return undefined
    } catch (error) {
      console.log('🚀 ~ getTokenListInfo ~ 82:', error)
      return undefined
    }
  }

  return {
    tokenInfo,
    getTokenInfo,
    getTokenListInfo,
    fetchTokenInfo
  }
}
